  const inventoryServices=lifecyclePoolServices('inventory',orderedServices);
  const batchServices=lifecyclePoolServices('batchOnly',legacyBatchServices);
  const localCount=state.services.filter(x=>x.kind.includes('本地')).length;
  const cloudCount=state.services.length-localCount;
  const routeCount=state.routes.filter(x=>x.operational).length;
  const summary={...summarizeServices(state.services),...(state.modelSummary||{})};
  const brain=state.replyBrain||{};
  const missing=Array.isArray(brain.missing)?brain.missing:[];
  const brainStatus=brain.pass===true?'回复大脑已就绪':'回复大脑尚未就绪';
  const openRouter=openRouterPolicySummary();
